draw:
var dU = p.Q - p.Wby;
ctx.font = '12px ui-sans-serif, system-ui, sans-serif';
ctx.textAlign = 'center';
ctx.textBaseline = 'middle';

var bx = W * 0.5, by = H * 0.5, bw = W * 0.30, bh = H * 0.40;

// the system box
ctx.strokeStyle = C.ink;
ctx.lineWidth = 2;
ctx.strokeRect(bx - bw / 2, by - bh / 2, bw, bh);
ctx.fillStyle = C.faint;
ctx.fillRect(bx - bw / 2, by - bh / 2, bw, bh);

ctx.fillStyle = C.ink;
ctx.fillText('the gas', bx, by - 16);
ctx.fillText('U changes by', bx, by + 4);
ctx.fillText((dU >= 0 ? '+' : '') + dU.toFixed(0) + ' J', bx, by + 22);

// arrow helper
function arrow(x1, y1, x2, y2, col) {
  ctx.strokeStyle = col;
  ctx.fillStyle = col;
  ctx.lineWidth = 2.5;
  ctx.beginPath();
  ctx.moveTo(x1, y1);
  ctx.lineTo(x2, y2);
  ctx.stroke();
  var a = Math.atan2(y2 - y1, x2 - x1);
  ctx.beginPath();
  ctx.moveTo(x2, y2);
  ctx.lineTo(x2 - 9 * Math.cos(a - 0.4), y2 - 9 * Math.sin(a - 0.4));
  ctx.lineTo(x2 - 9 * Math.cos(a + 0.4), y2 - 9 * Math.sin(a + 0.4));
  ctx.closePath();
  ctx.fill();
}

// heat arrow on the left: points in when Q > 0
var lx = bx - bw / 2, ox = W * 0.10;
var pulse = 1 + 0.12 * Math.sin(t * 2.2);
if (p.Q >= 0) { arrow(ox, by, lx - 6, by, C.accent); }
else { arrow(lx - 6, by, ox, by, C.accent); }
ctx.fillStyle = C.accent;
ctx.fillText('Q = ' + p.Q.toFixed(0) + ' J', (ox + lx) / 2, by - 20);
ctx.fillStyle = C.ink;
ctx.fillText(p.Q >= 0 ? 'heat in' : 'heat out', (ox + lx) / 2, by + 22);

// work arrow on the right: points out when W > 0
var rx = bx + bw / 2, oxr = W * 0.90;
if (p.Wby >= 0) { arrow(rx + 6, by, oxr, by, C.figure); }
else { arrow(oxr, by, rx + 6, by, C.figure); }
ctx.fillStyle = C.figure;
ctx.fillText('W = ' + p.Wby.toFixed(0) + ' J', (rx + oxr) / 2, by - 20);
ctx.fillStyle = C.ink;
ctx.fillText(p.Wby >= 0 ? 'work out' : 'work in', (rx + oxr) / 2, by + 22);

// piston cartoon on the right edge of the box, nudged by the work arrow
ctx.strokeStyle = C.rule;
ctx.lineWidth = 1;
var pistonX = rx - 10 + (p.Wby >= 0 ? 5 : -5) * pulse;
ctx.beginPath();
ctx.moveTo(pistonX, by - bh / 2 + 4);
ctx.lineTo(pistonX, by + bh / 2 - 4);
ctx.stroke();

ctx.fillStyle = C.ink;
ctx.fillText('first law:  change in U  =  Q  -  W', W * 0.5, H * 0.90);

out.note = 'dU = Q - W = ' + p.Q.toFixed(0) + ' - (' + p.Wby.toFixed(0) + ') = ' + dU.toFixed(0) + ' J';
